/* Live Supabase client. The publishable key is public; database RLS is the access boundary. */
const SUPABASE_URL='https://ykuwpfxzqqjuzihuoptb.supabase.co';
const PUBLISHABLE_KEY='sb_publishable_5VwThyzNR4rSFWkjV-aerw_z8UQ2uVD';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const years=['First year','Second year','Third year','Fourth year','Fifth year+','Graduate student'];
const db=window.supabase?.createClient(SUPABASE_URL,PUBLISHABLE_KEY,{auth:{flowType:'implicit',detectSessionInUrl:true,persistSession:true,autoRefreshToken:true}});
let user=null, profile=null, questions=[], answers=[], pastResults=[], matches=[], activeMatch=0;
let previewAnswers=[],previewQuestions=[],previewBusy=false,previewRun=0;
let welcomedUser=null;
let isAdmin=false;
let view='loading', fatal='', pendingEmail='', busy=false, resultsError='', matchesError='', loadedDay='', requestNumber=0, lastSent=0;
try{pendingEmail=sessionStorage.getItem('kinnect-pending-email')||'';lastSent=Number(sessionStorage.getItem('kinnect-last-sent')||0)}catch{}
function dateKey(offset=0){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const part=t=>p.find(x=>x.type===t).value;const d=new Date(Date.UTC(+part('year'),+part('month')-1,+part('day')+offset));return d.toISOString().slice(0,10)}
function errorMessage(e){const m=e?.message||'Something went wrong. Please try again.';if(/authorized|email_address_not_authorized/i.test(m))return 'The email sender could not deliver to this address. Please contact the Kinnect team.';if(/rate limit|too many|over_email_send_rate_limit/i.test(m))return 'The email sending limit was reached. Please wait before requesting another email.';return m}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function check(result){if(result.error)throw result.error;return result.data}
function complete(){return questions.length===3&&questions.every(q=>answers.some(a=>a.question_id===q.id))}
function header(){return `<header><button class="brand brand-home" data-view="welcome" aria-label="Kinnect home">Kinnect</button>${profile&&view!=='welcome'?`<nav class="nav" aria-label="Main navigation"><button data-view="today" class="${view==='today'?'active':''}">Today</button><button data-view="profile" class="${view==='profile'?'active':''}">Profile</button></nav>`:''}</header>`}
function loading(){return '<main class="join-page"><h2>Loading…</h2></main>'}
function login(){return `<main class="join-page"><div class="join-intro"><span class="small-head">CAL POLY, SLO</span><h1>Kinnect.</h1><p>Three daily questions.<br>Compare answers with other students.</p></div><form id="login-form"><label for="email">Cal Poly email</label><input id="email" type="email" name="email" placeholder="you@calpoly.edu" autocomplete="email" required><p class="error" id="form-error" role="alert"></p><button class="primary" type="submit">Send sign-in email</button><p class="fine">We’ll send a sign-in email. No password needed.</p><button class="link-btn" data-view="sent" type="button">Already have a code?</button></form></main>`}
function sent(){return `<main class="join-page"><h2>Check your email.</h2><p class="muted">Open the sign-in link, or enter the code from your email below.</p><form id="verify-form"><label for="verify-email">Cal Poly email</label><input id="verify-email" name="email" type="email" autocomplete="email" value="${esc(pendingEmail)}" placeholder="you@calpoly.edu" required><label for="token">Email code</label><input id="token" name="token" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6,10}" minlength="6" maxlength="10" placeholder="Enter your code" required><p class="error" id="form-error" role="alert"></p><button class="primary" type="submit">Verify and continue</button></form><p class="fine">Use the newest email. Check spam if you don’t see it.</p><button class="link-btn" data-view="login">Send another email</button></main>`}
function hasSeenWelcome(){if(welcomedUser===user?.id)return true;try{return sessionStorage.getItem('kinnect-welcome-'+user.id)==='seen'}catch{return false}}
function welcomeScreen(){const action=!user?'Get started':!profile?'Set up my profile':complete()?'See my results':'Start today’s questions';return `<main class="kinnect-landing minimalist-landing campus-home"><section class="landing-hero"><nav class="landing-nav" aria-label="Welcome navigation"><button class="landing-wordmark" data-view="welcome" aria-label="Kinnect home">KINNECT</button></nav><div class="minimal-guides" aria-hidden="true"></div><div class="world-copy"><p class="minimal-campus">CAL POLY · SAN LUIS OBISPO</p><h1>Three questions.<span>One campus.</span></h1><p class="world-description">Answer every day. See how Cal Poly thinks.<br> Meet people who think like you.</p><button class="primary landing-cta" id="welcome-continue" data-welcome-continue>${action}</button></div><a class="landing-scroll" href="#kinnect-story">Why we’re building it <span aria-hidden="true">↓</span></a></section><section class="landing-story about-short" id="kinnect-story"><div class="landing-section-inner"><p class="landing-eyebrow">WHY WE’RE BUILDING KINNECT</p><h2>Same campus.<br>Different circles.</h2><p class="landing-story-copy">It’s easy to stay in the same classes, the same circles, the same group chats.</p><p class="landing-story-copy about-last">We’re building Kinnect to make meeting someone new feel a little more natural.</p><button class="primary landing-cta" data-welcome-continue>${action}</button></div></section><footer class="landing-footer"><button data-view="welcome" aria-label="Kinnect home">Kinnect</button><span>Student-built. Not affiliated with Cal Poly.</span></footer><button class="mission-trigger" id="mission-open" aria-haspopup="dialog">Our mission</button><dialog class="mission-dialog" id="mission-dialog" aria-labelledby="mission-title"><div class="mission-card"><div class="mission-top"><span>OUR MISSION</span><button class="mission-close" id="mission-close" type="button">Close</button></div><h2 id="mission-title">Make a big campus<br>feel more connected.</h2><p>Help students discover common ground and turn a few shared answers into real conversations.</p><span class="mission-signature">Kinnect · Cal Poly</span></div></dialog></main>`}
function continueWelcome(){if(!user){view='login';render();window.scrollTo({top:0,behavior:'smooth'});return}welcomedUser=user.id;try{sessionStorage.setItem('kinnect-welcome-'+user.id,'seen')}catch{}view=profile?'today':'onboarding';render();window.scrollTo({top:0,behavior:'smooth'})}
function profileFields(p={}){return `<div class="row"><div><label for="first">First name</label><input id="first" name="first_name" value="${esc(p.first_name)}" maxlength="50" autocomplete="given-name" required></div><div><label for="last">Last name</label><input id="last" name="last_name" value="${esc(p.last_name)}" maxlength="50" autocomplete="family-name" required></div></div><label for="major">Major</label><input id="major" name="major" value="${esc(p.major)}" maxlength="100" required><label for="year">Year</label><select id="year" name="year">${years.map(y=>`<option ${y===p.year?'selected':''}>${y}</option>`).join('')}</select><label for="instagram">Instagram · optional</label><input id="instagram" name="instagram" value="${esc(p.instagram)}" placeholder="@username" maxlength="31" pattern="@?[A-Za-z0-9._]+"><label for="linkedin">LinkedIn · optional</label><input id="linkedin" name="linkedin" type="text" inputmode="url" autocomplete="url" value="${esc(p.linkedin)}" placeholder="https://www.linkedin.com/in/you">`}
function profileScreen(){const first=!profile;return `<main class="page"><div class="settings"><h2>${first?'Your profile.':'Edit profile.'}</h2><p class="fine">Signed in as ${esc(user.email)}</p><form id="profile-form">${profileFields(profile||{})}${first?'<label class="check"><input type="checkbox" name="consent" required><span>I agree to share my name, major, year, school email, and any socials I add with other verified students through matches.</span></label>':'<p class="fine">Your profile and contact details are visible to verified students who match with you.</p>'}<p class="error" id="form-error" role="alert"></p><button class="primary">${first?'Continue':'Save changes'}</button></form><button class="link-btn" data-view="welcome">About Kinnect</button> <button class="link-btn" id="start-preview">Preview questions</button> ${isAdmin?'<button class="link-btn" data-view="admin">Question admin</button>':''} <button class="link-btn" id="signout">Sign out</button></div></main>`}
function todayScreen(){if(questions.length!==3)return `<main class="page"><h2>No questions yet.</h2><p class="muted">Three questions haven’t been scheduled for today. Your saved answers are safe.</p><button class="link-btn" id="refresh">Check again</button></main>`;if(complete())return resultsScreen();const q=questions.find(q=>!answers.some(a=>a.question_id===q.id));const i=questions.indexOf(q);return `<main class="page"><div class="page-top"><span class="eyebrow">${esc(new Date().toLocaleDateString('en-US',{timeZone:'America/Los_Angeles',weekday:'long',month:'short',day:'numeric'}))}</span><span class="fine">${i+1} / 3</span></div><div class="play-layout"><section class="question-card"><div class="progress" aria-label="Question ${i+1} of 3">${questions.map((_,j)=>`<span class="${j<=i?'done':''}"></span>`).join('')}</div><h2>${esc(q.question_text)}</h2><div class="answers">${[q.option_a,q.option_b].map((text,n)=>`<button class="answer" data-answer="${n}" data-question="${esc(q.id)}"><strong>${esc(text)}</strong></button>`).join('')}</div><p class="error" id="answer-error" role="alert"></p><p class="fine">Your answer is saved when you select it.</p></section></div></main>`}
function resultsScreen(){return `<main class="page"><div class="section-title"><span class="eyebrow">TODAY’S THREE COMPLETE</span><h2>Campus results.</h2><p class="muted">Yesterday’s answers.</p></div>${resultsError?`<p class="notice">${esc(resultsError)}</p>`:pastResults.length?`<div class="result-grid">${pastResults.map((q,i)=>{const total=Number(q.votes_a)+Number(q.votes_b),a=total?Math.round(Number(q.votes_a)/total*100):0,b=total?100-a:0;return `<article class="card result"><span class="small-head muted">0${i+1}</span><h3>${esc(q.question_text)}</h3>${total?`<div class="number">${q.my_choice===1?b:a}<span style="font-size:24px">%</span></div><p class="fine">${q.my_choice!==null?'chose your answer':`chose “${esc(q.option_a)}”`}</p><div class="bar"><span style="width:${a}%"></span></div><div class="bar-legend"><span>${esc(q.option_a)}<br>${a}% ${q.my_choice===0?'· YOU':''}</span><span>${esc(q.option_b)}<br>${b}% ${q.my_choice===1?'· YOU':''}</span></div><p class="fine">${total} ${total===1?'response':'responses'}</p>`:'<p class="muted">No responses were recorded.</p>'}</article>`}).join('')}</div>`:'<p class="muted">No questions were recorded yesterday. Today’s results will appear tomorrow.</p>'}<div style="max-width:400px;margin:35px 0"><button class="primary" data-view="people">Your closest matches</button><button class="link-btn" data-view="share">Share your answers</button></div><p class="fine">Today’s answers are saved. New questions arrive at midnight Pacific.</p><button class="link-btn" id="refresh">Refresh results</button> <button class="link-btn" id="start-preview">Preview questions</button></main>`}
function peopleScreen(){return `<main class="page"><div class="section-title"><h2>Your matches.</h2></div>${matchesError?`<p class="notice">${esc(matchesError)}</p>`:matches.length?`<div class="match-grid">${matches.map((m,i)=>`<button class="card simple-match" data-match="${i}"><div><h3>${esc(m.first_name)} ${esc(m.last_name)}</h3><p class="muted">${esc(m.major)} · ${esc(m.year)}</p></div><div class="number">${Math.round(Number(m.same_answers)/Number(m.shared_answers)*100)}<span>%</span></div><span class="fine">${Number(m.same_answers)} of ${Number(m.shared_answers)} shared answers</span></button>`).join('')}</div><p class="fine">Based only on questions you both answered.${matches.some(m=>Number(m.shared_answers)<30)?' Early matches will change as you answer more questions.':''}</p>`:'<p class="muted">No matches yet. Another student needs to answer at least three of the same questions.</p>'}<button class="link-btn" data-view="today">Back to results</button></main>`}
function normalizeLinkedIn(value){const text=String(value||'').trim();if(!text)return '';return /^https?:\/\//i.test(text)?text:'https://'+text}
function safeSocial(value,type){try{if(type==='instagram'){const handle=value.replace(/^@/,'');return /^[a-z0-9._]{1,30}$/i.test(handle)?'https://www.instagram.com/'+encodeURIComponent(handle)+'/':null}const u=new URL(normalizeLinkedIn(value));return u.protocol==='https:'&&['linkedin.com','www.linkedin.com'].includes(u.hostname)?u.href:null}catch{return null}}
function matchScreen(){const m=matches[activeMatch];if(!m)return peopleScreen();const instagram=m.instagram&&safeSocial(m.instagram,'instagram'),linkedin=m.linkedin&&safeSocial(m.linkedin,'linkedin');return `<main class="page"><div class="profile-reveal"><button class="back" data-view="people">← Matches</button><div class="reveal-banner"><h2>${esc(m.first_name)} ${esc(m.last_name)}</h2><p>${esc(m.major)} · ${esc(m.year)}</p><div class="number reveal-score">${Math.round(Number(m.same_answers)/Number(m.shared_answers)*100)}<span>%</span></div><p>${Number(m.same_answers)} of ${Number(m.shared_answers)} shared answers</p></div><div class="contacts"><a class="contact" href="mailto:${esc(encodeURIComponent(m.email))}">School email <span>${esc(m.email)}</span></a>${instagram?`<a class="contact" href="${esc(instagram)}" target="_blank" rel="noopener noreferrer">Instagram <span>${esc(m.instagram)}</span></a>`:''}${linkedin?`<a class="contact" href="${esc(linkedin)}" target="_blank" rel="noopener noreferrer">LinkedIn <span>${esc(new URL(linkedin).hostname.replace(/^www\./,'')+new URL(linkedin).pathname.replace(/\/$/,''))} ↗</span></a>`:''}</div></div></main>`}
function shareScreen(){return `<main class="page"><div class="settings"><button class="back" data-view="today">← Results</button><h2>Share your answers.</h2><label class="check"><input type="checkbox" id="include-answers" checked>Include my answers</label><div class="share-preview"><span class="small-head">KINNECT · CAL POLY</span><div id="share-answers">${questions.map(q=>{const a=answers.find(a=>a.question_id===q.id);return `<p>${esc(q.question_text)}<br><strong>${esc(a?.choice===0?q.option_a:q.option_b)}</strong></p>`}).join('')}</div></div><button class="primary" id="share">Share</button></div></main>`}
function startPreview(){if(questions.length!==3){toast('No question set is available to preview yet.');return}previewRun++;previewQuestions=questions.map(q=>({...q}));previewAnswers=[];previewBusy=false;view='preview';render();window.scrollTo({top:0,behavior:'smooth'})}
function previewScreen(){const i=previewAnswers.length;if(i===previewQuestions.length)return `<main class="page"><div class="settings"><span class="eyebrow">PREVIEW · NOTHING SAVED</span><h2>Preview complete.</h2><p class="muted">Your real answers and matches haven’t changed.</p><div class="preview-recap">${previewQuestions.map((q,j)=>`<div class="preview-recap-row"><p>${esc(q.question_text)}</p><strong>${esc(previewAnswers[j]===0?q.option_a:q.option_b)}</strong></div>`).join('')}</div><button class="primary" id="start-preview">Run again</button><button class="link-btn" data-view="today">Exit preview</button></div></main>`;const q=previewQuestions[i];return `<main class="page"><div class="page-top"><span class="eyebrow">PREVIEW · ANSWERS NOT SAVED</span><button class="link-btn" data-view="today">Exit preview</button></div><div class="play-layout"><section class="question-card"><div class="progress" aria-label="Preview question ${i+1} of 3">${previewQuestions.map((_,j)=>`<span class="${j<=i?'done':''}"></span>`).join('')}</div><h2>${esc(q.question_text)}</h2><div class="answers">${[q.option_a,q.option_b].map((text,n)=>`<button class="answer" data-preview-answer="${n}"><strong>${esc(text)}</strong></button>`).join('')}</div><p class="fine">Question ${i+1} of 3 · Practice only</p></section></div></main>`}
function render(){const screens={admin:()=>window.KinnectAdmin.screen(),loading,login,sent,welcome:welcomeScreen,preview:previewScreen,onboarding:profileScreen,profile:profileScreen,today:todayScreen,people:peopleScreen,match:matchScreen,share:shareScreen,error:()=>`<main class="join-page"><h2>Couldn’t load the app.</h2><p class="error">${esc(fatal)}</p><button class="primary" id="refresh">Try again</button><button class="link-btn" id="signout">Sign out</button></main>`};$('#app').innerHTML=`<div class="shell" data-screen="${view}">${header()}${(screens[view]||loading)()}</div>`;bind()}
async function loadData(){const batch=++requestNumber;loadedDay=dateKey();try{const r=await db.rpc('is_kinnect_admin');isAdmin=r.data===true;if(!r.error)await db.rpc('ensure_daily_mix')}catch{isAdmin=false;}const [p,q,a]=await Promise.all([db.from('profiles').select('*').eq('id',user.id).maybeSingle(),db.from('questions').select('*').eq('question_date',loadedDay).order('position'),db.from('answers').select('question_id,choice').eq('user_id',user.id)]);const nextProfile=check(p),nextQuestions=check(q),nextAnswers=check(a);if(batch!==requestNumber)return;profile=nextProfile;questions=nextQuestions;answers=nextAnswers;if(!profile){view=hasSeenWelcome()?'onboarding':'welcome';render();return}if(complete())await loadResults();view=hasSeenWelcome()?'today':'welcome';render()}
async function loadResults(){const {data,error}=await db.rpc('campus_results',{target_date:dateKey(-1)});pastResults=data||[];resultsError=error?(error.code==='PGRST202'?'Results need the database update in supabase/02-live-results.sql. Your answers are saved.':errorMessage(error)):''}
async function navigate(next){if(next==='admin'){if(!isAdmin){toast('Admin access required.');return}view='admin';await window.KinnectAdmin.open({db,dateKey,esc,toast,render});render();window.scrollTo({top:0});return}if(['people','match','share'].includes(next)&&!complete()){toast('Finish today’s questions first.');return}if(next==='people'){view='loading';render();const {data,error}=await db.rpc('closest_matches');matches=data||[];matchesError=error?(error.code==='PGRST202'?'Matching needs the database update in supabase/02-live-results.sql.':errorMessage(error)):''}view=next;render();window.scrollTo({top:0,behavior:'smooth'})}
async function boot(){view='loading';render();if(!db){fatal='The sign-in library could not load. Refresh the page.';view='error';render();return}try{const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('error_description')){const message=hash.get('error_description');history.replaceState(null,'',location.pathname);throw Error(message)}const session=check(await db.auth.getSession()).session;if(!session){user=null;profile=null;view=pendingEmail?'sent':'login';render();return}user=check(await db.auth.getUser()).user;if(!user?.email_confirmed_at||!/@calpoly\.edu$/i.test(user.email)){await db.auth.signOut();user=null;throw Error('Sign in using your verified @calpoly.edu email.')}await loadData()}catch(e){fatal=errorMessage(e);view='error';render()}}
function bind(){if(view==='admin')window.KinnectAdmin.bind();$('#mission-open')?.addEventListener('click',()=>$('#mission-dialog').showModal());$('#mission-close')?.addEventListener('click',()=>$('#mission-dialog').close());$('#mission-dialog')?.addEventListener('click',e=>{if(e.target===$('#mission-dialog'))$('#mission-dialog').close()});document.querySelectorAll('[data-welcome-continue]').forEach(b=>b.onclick=continueWelcome);$('#start-preview')?.addEventListener('click',startPreview);document.querySelectorAll('[data-preview-answer]').forEach(b=>b.onclick=async()=>{if(previewBusy)return;const run=previewRun;previewBusy=true;b.classList.add('selected');document.querySelectorAll('[data-preview-answer]').forEach(x=>x.disabled=true);await new Promise(r=>setTimeout(r,430));if(view==='preview'&&run===previewRun){previewAnswers.push(+b.dataset.previewAnswer);render()}if(run===previewRun)previewBusy=false});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{activeMatch=+b.dataset.match;navigate('match')});
$('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const email=new FormData(e.target).get('email').trim().toLowerCase();if(!/^[^\s@]+@calpoly\.edu$/.test(email)){$('#form-error').textContent='Use your @calpoly.edu email.';return}if(Date.now()-lastSent<60000){$('#form-error').textContent='Wait a minute before sending another link.';return}busy=true;const button=e.target.querySelector('button');button.disabled=true;button.textContent='Sending…';try{const redirect=location.origin+location.pathname;check(await db.auth.signInWithOtp({email,options:{emailRedirectTo:redirect,shouldCreateUser:true}}));lastSent=Date.now();pendingEmail=email;try{sessionStorage.setItem('kinnect-pending-email',email);sessionStorage.setItem('kinnect-last-sent',String(lastSent))}catch{}view='sent';render()}catch(err){$('#form-error').textContent=errorMessage(err);button.disabled=false;button.textContent='Send sign-in email'}finally{busy=false}});
$('#verify-form')?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.target),email=f.get('email').trim().toLowerCase(),token=f.get('token').trim();if(!/^[^\s@]+@calpoly\.edu$/.test(email)){$('#form-error').textContent='Use your @calpoly.edu email.';return}if(!/^[0-9]{6,10}$/.test(token)){$('#form-error').textContent='Enter the code exactly as shown in your email.';return}busy=true;const button=e.target.querySelector('button');button.disabled=true;button.textContent='Verifying…';try{check(await db.auth.verifyOtp({email,token,type:'email'}));pendingEmail='';try{sessionStorage.removeItem('kinnect-pending-email')}catch{}await boot()}catch(err){$('#form-error').textContent=/expired|invalid|otp_expired/i.test(errorMessage(err))?'This code is invalid or expired. Use the newest email, or request another code.':errorMessage(err);button.disabled=false;button.textContent='Verify and continue'}finally{busy=false}});
$('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.target),linkedin=normalizeLinkedIn(f.get('linkedin')),instagram=f.get('instagram').trim();const input={first_name:f.get('first_name').trim(),last_name:f.get('last_name').trim(),major:f.get('major').trim(),year:f.get('year'),instagram:instagram||null,linkedin:linkedin||null};if(!input.first_name||!input.last_name||!input.major){$('#form-error').textContent='Complete your name and major.';return}if(linkedin&&!safeSocial(linkedin,'linkedin')){$('#form-error').textContent='Use an https://www.linkedin.com/ profile URL.';return}if(!profile&&f.get('consent')!=='on')return;busy=true;const button=e.target.querySelector('button');button.disabled=true;try{if(profile){profile=check(await db.from('profiles').update(input).eq('id',user.id).select().single());toast('Profile saved.')}else{profile=check(await db.from('profiles').insert({...input,id:user.id,sharing_agreed_at:new Date().toISOString()}).select().single());await loadData()}}catch(err){$('#form-error').textContent=errorMessage(err)}finally{busy=false;if(button.isConnected)button.disabled=false}});
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=async()=>{if(busy)return;if(loadedDay!==dateKey()){await boot();return}busy=true;const questionId=b.dataset.question,choice=+b.dataset.answer;b.classList.add('selected');document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);try{const delay=new Promise(r=>setTimeout(r,430));const result=await db.from('answers').insert({user_id:user.id,question_id:questionId,choice});if(result.error){if(result.error.code==='23505'){toast('This answer was already saved.');await loadData();return}throw result.error}answers.push({question_id:questionId,choice});await delay;if(complete())await loadResults();view='today';render()}catch(err){if($('#answer-error'))$('#answer-error').textContent=errorMessage(err);document.querySelectorAll('[data-answer]').forEach(x=>{x.disabled=false;x.classList.remove('selected')})}finally{busy=false}});
$('#refresh')?.addEventListener('click',()=>boot());$('#signout')?.addEventListener('click',async()=>{const {error}=await db.auth.signOut();if(error){toast(errorMessage(error));return}requestNumber++;try{sessionStorage.removeItem('kinnect-welcome-'+user.id)}catch{}welcomedUser=null;user=null;profile=null;questions=[];answers=[];matches=[];pastResults=[];view='login';render()});$('#include-answers')?.addEventListener('change',e=>{$('#share-answers').hidden=!e.target.checked});$('#share')?.addEventListener('click',async()=>{const lines=$('#include-answers').checked?questions.map(q=>{const a=answers.find(a=>a.question_id===q.id);return q.question_text+' → '+(a.choice===0?q.option_a:q.option_b)}).join('\n'):'';const text=`Kinnect · Cal Poly\n${lines}\n${location.origin+location.pathname}`;try{if(navigator.share)await navigator.share({title:'Kinnect',text});else{await navigator.clipboard.writeText(text);toast('Copied.')}}catch(e){if(e.name!=='AbortError')toast('Could not share. Copy the page address instead.')}})}
setInterval(()=>{if(user&&loadedDay!==dateKey()&&!busy&&view!=='preview'&&view!=='welcome'&&view!=='admin')boot()},30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&user&&!busy&&view!=='preview'&&view!=='welcome'&&view!=='admin')boot()});
boot();
